mapper.insert:
insert into t_board(subject, detail, writer, reg_dt, reg_id, mod_dt, mod_id)
values(
    #{subject}
    , #{detail}
    , #{writer}
    , NOW()
    , #{regId}
    , NOW()
    , #{modId}
)

insert into t_board_attach(board_seq, file_nm, origin_file_nm, path, ext, reg_dt, reg_id, mod_dt, mod_id)
values(#{boardSeq}
    , #{fileNm}
    , #{originFileNm}
    , #{path}
    , #{ext}
    , NOW()
    , #{regId}
    , NOW()
    , #{modId}
)

mapper.select:
select count(*)
from t_board
where 1=1

        and subject = #{subject}


        and writer = #{writer}

select t1.num , t1.seq , t1.subject , t1.detail , t1.writer , t1.reg_dt , t1.reg_id , t1.mod_dt , t1.mod_id , t2.seq AS attach_seq , t2.file_nm , t2.origin_file_nm , t2.path , t2.ext from ( select @num:=@num+1 AS num , seq , subject , detail , writer , reg_dt , reg_id , mod_dt , mod_id from (select @num:=0) a, t_board
AND subject = #{subject}
AND writer = #{writer}
where 1=1 order by num desc limit #{offset}, #{limit} ) t1 left outer join t_board_attach t2 on t1.seq = t2.board_seq and t2.del_yn = 'N' where 1=1 order by t1.num desc

select status
from t_trx_status
where trx_id = #{trxId}
